import {ContributionsView} from '../../src/features/contributions.ts';import {contributionPhoto} from '../../src/platform/contributions.ts';
export function createContributionFixture(){let uploads:any[]=[],reviews:string[]=[],confirm=true,pending=false,late:((r:any)=>void)|undefined,readFail=false,result='sent',cancels=0;const entries=Array.from({length:13},(_,i)=>({version:1 as const,id:(i+1).toString(16).padStart(64,'0'),experimentId:'abcdef123456',section:'实验原理',index:0,original:'原文',text:`第${i+1}条 <script>正文</script>`,createdAt:'2026-10-25T00:00:00Z'}));const view=new ContributionsView([{id:'abcdef123456',name:'实验一',sourceId:'官方实验一'},{id:'123456abcdef',name:'实验二',sourceId:'官方实验二'}],{version:'0.34.0',list:async id=>id==='abcdef123456'?entries.map(e=>({...e,preview:e.text})):[],read:async(id,key)=>{if(readFail)throw Error('变体读取失败');const row=entries.find(e=>e.id===key);if(!row||row.experimentId!==id)throw Error('归属错误');return row;},localWord:async()=>({name:'本机报告.docx',bytes:Uint8Array.from([80,75,3,4])}),photo:contributionPhoto,confirm:async body=>{reviews.push(body);return confirm;},upload:async(id,exp,kind,files)=>{uploads.push({id,exp,kind,files:files.map(f=>({name:f.name,size:f.bytes.length,text:f.name.endsWith('.json')?new TextDecoder().decode(f.bytes):''}))});if(pending)return new Promise<any>(r=>late=r);return {state:result as any,sent:result==='sent'?files.length:1,total:files.length};},cancel:async()=>{cancels++;late?.({state:'cancelled',sent:0,total:1})}});const mount=()=>view.mount(document.querySelector<HTMLElement>('#contribution-host')!);mount();return {state:()=>({uploads,reviews,cancels,busy:view.isSaving}),confirm:(v:boolean)=>confirm=v,result:(v:string)=>result=v,readFail:()=>readFail=true,pending:()=>pending=true,resolve:()=>late?.({state:'sent',sent:1,total:1}),leave:()=>view.leave(),reopen:mount};}
